begin;
select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987122001,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Raynor Winn vertelt hoe zij en haar man Moth na het verlies van hun huis en zorgelijk nieuws over zijn gezondheid besluiten langs de Engelse kust te wandelen. Met weinig middelen volgen ze het South West Coast Path. De tocht brengt lichamelijke belasting, onzekerheid en ontmoetingen met onbekenden. Winn beschrijft hoe het landschap hun dagelijks bestaan gaat bepalen. Het boek is haar persoonlijke relaas over verlies, samen verdergaan en de zoektocht naar houvast buiten een vertrouwde woonplek.","work_id":987122001,"evidence":[{"note":"Primary Balans explicitly lists exact Dutch paperback9789463821513; KB agrees. Preserve verified book/translation identity. Summary is attributed to Winn as her personal memoir, not independent certification of medical or biographical claims. Do not substitute publisher current filmprint or ebook ISBNs.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p431096511","http://data.bibliotheken.nl/id/nbt/p433740027"],"reference":"work:1461","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.uitgeverijbalans.nl/boeken/het-zoutpad/","https://openlibrary.org/works/OL20153160W","https://data.bibliotheken.nl/id/nbt/p431096511","https://data.bibliotheken.nl/id/nbt/p433740027"]},{"type":"cover_front_review","sha256":"c8c3fba14a538bb15323193667e5051e4e9c43496ad5bdfd7cb7b0551ffc6463","cover_id":12667409,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.uitgeverijbalans.nl/boeken/het-zoutpad/","reviewed_at":"2026-11-02T22:05:23.248+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_author_id":987322001},"before_row":null},{"key":{"edition_id":987222001},"seq":2,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987122001,"evidence":[{"note":"Primary Balans explicitly lists exact Dutch paperback9789463821513; KB agrees. Preserve verified book/translation identity. Summary is attributed to Winn as her personal memoir, not independent certification of medical or biographical claims. Do not substitute publisher current filmprint or ebook ISBNs.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p431096511","http://data.bibliotheken.nl/id/nbt/p433740027"],"reference":"work:1461","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.uitgeverijbalans.nl/boeken/het-zoutpad/","https://openlibrary.org/works/OL20153160W","https://data.bibliotheken.nl/id/nbt/p431096511","https://data.bibliotheken.nl/id/nbt/p433740027"]},{"type":"cover_front_review","sha256":"c8c3fba14a538bb15323193667e5051e4e9c43496ad5bdfd7cb7b0551ffc6463","cover_id":12667409,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/12667409-L.jpg?default=false","edition_id":987222001,"bound_title":"Het Zoutpad","reviewed_at":"2026-11-02T22:05:23.248+00:00","bound_isbn13":"9789463821513","evidence_url":"https://data.bibliotheken.nl/id/nbt/p431096511","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12667409-M.jpg?default=false","bound_author_id":987322001},"before_row":null},{"key":{"id":987222003},"seq":3,"relation":"editions","after_row":{"id":987222003,"title":"Het Kwade Uur","isbn_10":"9029015837","isbn_13":"9789029015837","work_id":987122002,"cover_id":null,"language":"dut","publisher":"Meulenhoff","publish_date":null,"open_library_edition_id":"OL12802602M"},"before_row":{"id":987222003,"title":"Het Kwade Uur","isbn_10":"9029015837","isbn_13":null,"work_id":987122002,"cover_id":null,"language":"dut","publisher":"Meulenhoff","publish_date":null,"open_library_edition_id":"OL12802602M"}},{"key":{"work_id":987122002,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"In een Colombiaans dorp verschijnen anonieme briefjes die de privégeheimen van bewoners openbaar maken. Veel ervan was als gerucht al bekend, maar op schrift krijgen de beschuldigingen een andere kracht. Wanneer een man een vermeende minnaar van zijn vrouw doodt, grijpt de burgemeester in. De ontstane onrust biedt hem tegelijk gelegenheid zijn politieke tegenstanders aan te pakken. García Márquez laat zien hoe persoonlijke vernedering en bestuurlijke macht elkaar kunnen versterken in een gemeenschap waar het geweld slechts tijdelijk tot rust leek gekomen.","work_id":987122002,"evidence":[{"note":"Exact Dutch Meulenhoff paperback9789029015837 is bound by OL12802602M and KBp830788220; fill only missingISBN. Source person OL27363A and exact book authority p068803680 shareQ5878/VIAF54147956/ISNI0000000121333785; Gabriel and GabrielJosé resolved independently.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p830788220"],"reference":"work:1485","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":"Shared person Q5878/VIAF54147956/ISNI0000000121333785. No name-only merge."},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://openlibrary.org/works/OL274539W","https://data.bibliotheken.nl/id/nbt/p830788220"]},{"type":"cover_front_review","sha256":"73da1bd5f68107d8df92f9e3d5181e494c74c2f8709233db951e432ace879817","cover_id":13057284,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL274539W","reviewed_at":"2026-11-02T22:05:23.248+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_author_id":928300035},"before_row":null},{"key":{"edition_id":987222003},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987122002,"evidence":[{"note":"Exact Dutch Meulenhoff paperback9789029015837 is bound by OL12802602M and KBp830788220; fill only missingISBN. Source person OL27363A and exact book authority p068803680 shareQ5878/VIAF54147956/ISNI0000000121333785; Gabriel and GabrielJosé resolved independently.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p830788220"],"reference":"work:1485","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":"Shared person Q5878/VIAF54147956/ISNI0000000121333785. No name-only merge."},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://openlibrary.org/works/OL274539W","https://data.bibliotheken.nl/id/nbt/p830788220"]},{"type":"cover_front_review","sha256":"73da1bd5f68107d8df92f9e3d5181e494c74c2f8709233db951e432ace879817","cover_id":13057284,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13057284-L.jpg?default=false","edition_id":987222003,"bound_title":"Het Kwade Uur","reviewed_at":"2026-11-02T22:05:23.248+00:00","bound_isbn13":"9789029015837","evidence_url":"https://data.bibliotheken.nl/id/nbt/p830788220","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13057284-M.jpg?default=false","bound_author_id":928300035},"before_row":null},{"key":{"work_id":987122005,"language":"nl"},"seq":6,"relation":"catalog_work_descriptions","after_row":{"text":"Deze bundel verenigt tien vroege verhalen van Roald Dahl over vliegen en vliegers. Veel ervan spelen in de Tweede Wereldoorlog en bouwen voort op de wereld die hij zelf als piloot leerde kennen. Onder de opgenomen teksten staat ook zijn eerste betaalde verhaal, dat aanvankelijk onder een andere titel verscheen. Het boek laat daarmee een vroeg gedeelte van zijn schrijverschap zien. De ervaringen uit de luchtvaart vormen een gezamenlijke achtergrond, zonder dat de verhalen daardoor als letterlijke memoires moeten worden gelezen.","work_id":987122005,"evidence":[{"note":"Exact1988Dutch Meulenhoff paperback9789029035729 is OverToYou in KB and OL; DeSlegte exactISBN explicitly describes ten pilot stories. Same full ten-story collection, not literal autobiography. TranslatorPeterVerstegen not a primary coauthor.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p048702803"],"reference":"work:4958","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-027.json","sources":["https://www.deslegte.com/over-en-sluiten-404570/","https://openlibrary.org/works/OL45867W","https://data.bibliotheken.nl/id/nbt/p048702803"]},{"type":"cover_front_review","sha256":"43da27dd8bb40ef41dc407501e623503105fd65b7d27ee548a21cd0311afe460","cover_id":12003708,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.deslegte.com/over-en-sluiten-404570/","reviewed_at":"2026-11-02T22:05:23.248+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_author_id":978300032},"before_row":null},{"key":{"edition_id":987222007},"seq":7,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987122005,"evidence":[{"note":"Exact1988Dutch Meulenhoff paperback9789029035729 is OverToYou in KB and OL; DeSlegte exactISBN explicitly describes ten pilot stories. Same full ten-story collection, not literal autobiography. TranslatorPeterVerstegen not a primary coauthor.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p048702803"],"reference":"work:4958","checked_at":"2026-11-02T22:05:23.248Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-027.json","sources":["https://www.deslegte.com/over-en-sluiten-404570/","https://openlibrary.org/works/OL45867W","https://data.bibliotheken.nl/id/nbt/p048702803"]},{"type":"cover_front_review","sha256":"43da27dd8bb40ef41dc407501e623503105fd65b7d27ee548a21cd0311afe460","cover_id":12003708,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/12003708-L.jpg?default=false","edition_id":987222007,"bound_title":"Over en Sluiten","reviewed_at":"2026-11-02T22:05:23.248+00:00","bound_isbn13":"9789029035729","evidence_url":"https://data.bibliotheken.nl/id/nbt/p048702803","review_batch":"nl-scale-20261102-023","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12003708-M.jpg?default=false","bound_author_id":978300032},"before_row":null},{"key":{"id":987222008},"seq":8,"relation":"editions","after_row":{"id":987222008,"title":"De jongeman","isbn_10":"9029549777","isbn_13":"9789029549776","work_id":987122006,"cover_id":null,"language":"dut","publisher":"Uitgeverij De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL47082597M"},"before_row":{"id":987222008,"title":"De jongeman","isbn_10":"9029549777","isbn_13":"9789029549776","work_id":987122006,"cover_id":null,"language":"dut","publisher":null,"publish_date":null,"open_library_edition_id":"OL47082597M"}},{"key":{"work_id":987122006,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"In de jaren negentig begint Annie Ernaux een verhouding met een man die bijna dertig jaar jonger is. Zijn eenvoudige studentenbestaan in Rouen roept herinneringen op aan haar eigen jeugd in dezelfde stad. Hun contact maakt leeftijdsverschil en verstreken tijd tegelijk voelbaar. Reizen en gedeelde ervaringen brengen hen dichter bij elkaar, terwijl de blik van anderen de verhouding een andere betekenis geeft. Ernaux gebruikt deze persoonlijke geschiedenis om te onderzoeken hoe een nieuw verlangen ook een terugkeer naar een vroeger zelf kan worden.","work_id":987122006,"evidence":[{"note":"Primary Arbeiderspers and KBp437779300 bind exact2023Dutch paperback9789029549776/RokusHofstede translation and afterword. Distinct ebook/audioISBNs not imported; accessibleDaisy reuse of printISBN not mistaken for print. Fill missing stored publisher from exact library publication statement.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p437779300"],"reference":"work:5180","checked_at":"2026-11-02T22:05:23.248Z","stored_fields_review":{"after":{"publisher":"Uitgeverij De Arbeiderspers"},"isbn13":"9789029549776","reason":"Primary Arbeiderspers and KBp437779300 bind exact2023Dutch paperback9789029549776/RokusHofstede translation and afterword. Distinct ebook/audioISBNs not imported; accessibleDaisy reuse of printISBN not mistaken for print. Fill missing stored publisher from exact library publication statement.","sources":["https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-jon